const defaults = {
  first_name: 'contenu illisible',
  last_name: 'contenu illisible',
  date_of_birth: 'contenu illisible',
  document_number: 'contenu illisible',
  document_type: 'other',
  expiry_date: 'contenu illisible'
};

const input = $json || {};
const body = input.body || {};
const rawSchema = body.output ?? input.output ?? '';

let parsedSchema = null;
if (typeof rawSchema === 'string' && rawSchema.trim()) {
  try { parsedSchema = JSON.parse(rawSchema); } catch { parsedSchema = null; }
} else if (rawSchema && typeof rawSchema === 'object') {
  parsedSchema = rawSchema;
}

const schemaObj = (parsedSchema && typeof parsedSchema === 'object' && !Array.isArray(parsedSchema))
  ? parsedSchema
  : defaults;

const schema = {};
for (const k of Object.keys(schemaObj)) schema[k] = 'contenu illisible';
if (!schema.document_type) schema.document_type = 'other';

const prompt = (input.chatInput ?? body.chatInput ?? body.prompt ?? 'carte ci-jointe').toString();

return [{
  json: {
    ...input,
    prompt,
    schema,
    schemaString: JSON.stringify(schema)
  },
  binary: $binary
}];

const raw = ($json.res || '').toString().trim();

function extractFirstJsonBlock(text) {
  const start = text.indexOf('{');
  if (start < 0) return null;
  let depth = 0;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (ch === '{') depth++;
    if (ch === '}') {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  return null;
}

const jsonBlock = extractFirstJsonBlock(raw);
let modelObj = {};
if (jsonBlock) {
  try { modelObj = JSON.parse(jsonBlock); } catch { modelObj = {}; }
}

const schema = ($json.schema && typeof $json.schema === 'object') ? $json.schema : {
  first_name: 'contenu illisible',
  last_name: 'contenu illisible',
  date_of_birth: 'contenu illisible',
  document_number: 'contenu illisible',
  document_type: 'other',
  expiry_date: 'contenu illisible'
};

const out = {};
for (const k of Object.keys(schema)) {
  const v = modelObj[k];
  out[k] = (v === undefined || v === null || `${v}`.trim() === '') ? 'contenu illisible' : v;
}
if (!out.document_type || out.document_type === 'contenu illisible') out.document_type = 'other';

return [{ json: { ...$json, outputJson: out } }];

